package org.dromara.property.resident.service.impl;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page; import lombok.RequiredArgsConstructor; import org.dromara.common.core.domain.PageResult; import org.dromara.common.core.exception.ServiceException; import org.dromara.common.mybatis.core.page.PageQuery; import org.dromara.property.resident.domain.bo.ResidentQueryBo; import org.dromara.property.resident.domain.vo.*; import org.dromara.property.resident.mapper.ResidentMapper; import org.dromara.property.resident.service.IResidentService; import org.dromara.property.scope.*; import org.springframework.stereotype.Service; import java.util.*;
/** 基于 Customer 与 RoomCustomerRelation 的项目住户只读视图。 */
@Service @RequiredArgsConstructor public class ResidentServiceImpl implements IResidentService {
 private final ResidentMapper residentMapper; private final PropertyProjectScopeService scopeService; private final PropertyFunctionalPermissionService functionalPermissionService;
 public PageResult<ResidentRelationVo> queryPage(ResidentQueryBo bo,PageQuery pq){var s=scope(ProjectBusinessAction.READ,"property:resident:list");if(!s.contains(bo.getProjectId()))return PageResult.build(List.of(),0L);Page<ResidentRelationVo> p=residentMapper.selectPage(pq.build(),bo,ids(s));return PageResult.build(p.getRecords(),p.getTotal());}
 public ResidentDetailVo queryDetail(Long customerId,Long projectId){var s=scope(ProjectBusinessAction.READ,"property:resident:query");if(projectId!=null&&!s.contains(projectId))throw new ServiceException("无项目业务访问权限");var rs=residentMapper.selectCustomerRelations(customerId,projectId,ids(s));if(rs.isEmpty())throw new ServiceException("住户不存在或不在当前项目业务范围内");var f=rs.getFirst();var d=new ResidentDetailVo();d.setCustomerId(f.getCustomerId());d.setCustomerNo(f.getCustomerNo());d.setCustomerType(f.getCustomerType());d.setCustomerName(f.getMaskedCustomerName());d.setMobile(f.getMaskedMobile());d.setStatus(f.getCustomerStatus());d.setLifecycleStatus(f.getCustomerLifecycleStatus());d.setCurrentRelations(rs.stream().filter(x->"ACTIVE".equals(x.getRelationStatus())).toList());d.setPendingRelations(rs.stream().filter(x->"PENDING".equals(x.getRelationStatus())).toList());d.setHistoryRelations(rs.stream().filter(x->"ENDED".equals(x.getRelationStatus())).toList());return d;}
 public List<ResidentExportVo> queryExport(ResidentQueryBo bo){var s=scope(ProjectBusinessAction.EXPORT,"property:resident:export");if(!s.contains(bo.getProjectId()))return List.of();return residentMapper.selectList(bo,ids(s)).stream().map(this::export).toList();}
 private PropertyProjectScope scope(ProjectBusinessAction a,String p){functionalPermissionService.assertCurrent(p);return scopeService.resolveBusinessScope(PropertyBusinessDomain.CUSTOMER_RELATION,a);} private Collection<Long> ids(PropertyProjectScope s){return s.type()==PropertyProjectScope.Type.EXPLICIT_IDS?s.projectIds():null;}
 private ResidentExportVo export(ResidentRelationVo s){var t=new ResidentExportVo();t.setCustomerNo(s.getCustomerNo());t.setMaskedCustomerName(s.getMaskedCustomerName());t.setMaskedMobile(s.getMaskedMobile());t.setRelationType(s.getRelationType());t.setBuildingName(s.getBuildingName());t.setUnitName(s.getUnitName());t.setRoomNo(s.getRoomNo()==null?s.getRoomCode():s.getRoomNo());t.setRelationStatus(s.getRelationStatus());t.setMoveInDate(s.getMoveInDate());t.setMoveOutDate(s.getMoveOutDate());return t;}
}
